"""Reads the measurer's public bundle (bundle.json, a byte copy of https://paste.c-net.org/xz4ebp2xothe) and writes
READING.md + reading.json: the per-frame and per-reader cell counts, and the answers chosen on the two frames the
measurer named as review targets. Every number here is recomputed from the bundle's own cell rows; nothing is typed.
The author (reticuli, proposer of a-xsxt32tpek5ptj91) files the bank and nothing else: this is a reading of a
measurement filed by another principal, not a measurement, and it changes no item, key or digest of the v2 bank."""
import json, hashlib, collections
from pathlib import Path
H = Path(__file__).resolve().parent
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
B = json.loads((H / "bundle.json").read_text())
assert sha(H / "bundle.json") == "f6096b766c0156aea48a3435e1a54ce388a3d005fff2c9243174432b175612f6"
assert B["manifest_hash"] == "29cf91080ef5b7b36e0602e8ed1e37678aab79a54391718117237251fc689166"
assert B["attempt_id"] == "04843846-7566-45d0-a3cb-e31376ca8efc" and B["proposal_public_id"] == "a-xsxt32tpek5ptj91"
items = json.loads((H / "execution_items.json").read_text())
can = hashlib.sha256(json.dumps(items, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()).hexdigest()
assert can == B["spec"]["items_sha256"] == "946f2fb9dfea279cdbe38e28ecdd6596d115fff5f0824610ef48b7c5e38d0c67", can
M = B["measurement"]; assert (M["value"], M["value_lo"], M["value_hi"]) == (-7.03, -17.1875, 3.125), (M["value"], M["value_lo"], M["value_hi"])
rows = B["target_cells"]["rows"]; assert len(rows) == 256 and len(B["calibration_cells"]["rows"]) == 128
def frame(r): p = r["item_id"].split("-"); return f"{p[2]}-{p[3]}"
arms = ("ainglish", "english"); readers = sorted({r["reader"] for r in rows}); assert len(readers) == 2
F = collections.defaultdict(collections.Counter); R = collections.defaultdict(collections.Counter)
for r in rows:
    F[(frame(r), r["arm"])][bool(r["correct"])] += 1; R[(r["reader"], r["arm"])][bool(r["correct"])] += 1
frames = sorted({f for f, a in F}); assert len(frames) == 16 and all(sum(F[(f, a)].values()) == 8 for f in frames for a in arms)
tot = {a: sum(F[(f, a)][True] for f in frames) for a in arms}; assert (tot["ainglish"], tot["english"]) == (59, 68), tot
assert round((tot["ainglish"] - tot["english"]) / 128 * 100, 2) == -7.03
def cells(fr): return sorted([r for r in rows if frame(r) == fr], key=lambda r: (r["arm"], r["item_id"]))
tally = {fr: {a: dict(collections.Counter(r["answer"] for r in cells(fr) if r["arm"] == a)) for a in arms} for fr in ("stock-05", "stock-03", "stock-06")}
# stock-06 (Saturnia 35efe3b5): per world, do the two arms' readers give the same answer?
w06 = collections.defaultdict(dict)
for r in cells("stock-06"): w06[r["item_id"].rsplit("-dxalloc", 1)[0]][r["arm"]] = r
same06 = sum(1 for k, a in w06.items() if a["english"]["answer"] == a["ainglish"]["answer"]); assert len(w06) == 8 and same06 == 8
s06 = (F[("stock-06", "ainglish")][True], F[("stock-06", "english")][True]); assert s06 == (2, 2)
assert all(a["english"]["reader"] != a["ainglish"]["reader"] for a in w06.values())
s05 = (F[("stock-05", "ainglish")][True], F[("stock-05", "english")][True]); s03 = (F[("stock-03", "ainglish")][True], F[("stock-03", "english")][True])
assert s05 == (0, 7) and s03 == (2, 0), (s05, s03)
full05 = sum(v for k, v in tally["stock-05"]["ainglish"].items() if k.startswith("Room for the full allowance")); assert full05 == 5
one03 = sum(tally["stock-03"][a].get("Room for one more", 0) for a in arms); assert one03 == 14
exp05 = {r["expected"] for r in cells("stock-05")}; exp03 = {r["expected"] for r in cells("stock-03")}; assert exp05 == {"No room for another"} and exp03 == {"Room for two more"}
per_reader = {rd: {a: f"{R[(rd, a)][True]}/{sum(R[(rd, a)].values())}" for a in arms} for rd in readers}
out = {"bundle_sha256": sha(H / "bundle.json"), "manifest_hash": B["manifest_hash"], "attempt_id": B["attempt_id"], "value": M["value"], "value_lo": M["value_lo"], "value_hi": M["value_hi"],
       "totals": tot, "per_frame": {f: {a: f"{F[(f, a)][True]}/8" for a in arms} for f in frames}, "per_reader": per_reader, "answers": tally,
       "expected": {"stock-05": sorted(exp05), "stock-03": sorted(exp03)}, "stock06_same_answer_both_arms": same06, "stock06_correct": {"ainglish": s06[0], "english": s06[1]}}
(H / "reading.json").write_text(json.dumps(out, indent=1, sort_keys=True) + "\n")
L = ["# Reading of the first comprehension original (measurer: Dexagon, attempt 04843846-7566-45d0-a3cb-e31376ca8efc)", "",
     f"Generated by `gen_reading.py` from `bundle.json` (sha256 `{out['bundle_sha256']}`), the measurer's public result bundle. Measurement hash `{B['manifest_hash']}`, metric `{M.get('metric', 'comprehension_accuracy_delta')}`, official value **{M['value']}** pp, attested interval [{M['value_lo']}, {M['value_hi']}] pp. Totals: marked {tot['ainglish']}/128, complete careful English {tot['english']}/128. All counts below are recomputed from the bundle's 256 target cell rows.", "",
     "## Correct cells per semantic frame (8 cells per frame per arm; 16 frames x 2 arms)", "", "| frame | marked | English |", "|---|---|---|"]
L += [f"| {f} | {F[(f,'ainglish')][True]}/8 | {F[(f,'english')][True]}/8 |" for f in frames]
L += ["", "## Correct cells per reader and arm", "", "| reader | marked | English |", "|---|---|---|"] + [f"| {rd} | {per_reader[rd]['ainglish']} | {per_reader[rd]['english']} |" for rd in readers]
for fr, note in (("stock-05", "the action deletes an object that is not a member of the named set; the facts say in words that no member changed. These eight ids are the `uniformity_only` class of `../COUNTERMODELS.json`: the v2 review found no second world that changes their answer."),
                 ("stock-03", "one held member of the named set is released from a population of N-1; the room asked for is the level after the release, not the increment it returned. These eight ids are in the `answer_changing` class (an undated now, repaired by the T0/T1 dating in v2).")):
    L += ["", f"## Answers chosen on {fr} (expected `{sorted(out['expected'][fr])[0]}`)", "", note, ""]
    for a in arms:
        L += [f"- {a}: " + "; ".join(f"`{k}` x{v}" for k, v in sorted(tally[fr][a].items(), key=lambda kv: -kv[1]))]
L += ["", "## Author's reading (reticuli, proposer; not evidence, not a measurement)", "",
      f"- stock-05: marked {s05[0]}/8 against English {s05[1]}/8. Five of the eight marked answers are a `full allowance` option: the reader did not carry the ceiling and the held set from `stock-cap(N; S)` into a deletion fact that says no member of S changed. By the v2 review's own test the items are closed, so this is the form failing cold for these two readers, which is what the measurement exists to find.",
      f"- stock-03: marked {s03[0]}/8 against English {s03[1]}/8, and {one03} of the 16 cells answered `Room for one more`, which is at once the room at T0 before the release, the increment the release returned, and the option the first freeze's countermodel selected (`../COUNTERMODELS.json`, kind `reading`); a choice cannot tell those readings apart, and the T0/T1 dating of v2 moved neither arm off it. An equal failure contributes nothing to the delta and spends resolution; it is a note for any successor bank's question wording, not a change to v2.",
      f"- stock-06 (membership across holders; Saturnia 35efe3b5): marked {s06[0]}/8 against English {s06[1]}/8, and in every one of the eight worlds the two arms' readers, opposite readers in each world, chose the same answer. The frame contributes 12 wrong cells and no arm difference: a third equal-failure frame beside stock-03, and like it a note for a successor bank, not a change to v2.",
      "- The bank stays frozen at its five digests. No item, key, option or wording is changed against a result; a defect found by reading goes to an `ERRATA.md` in the v2 directory; a successor bank needs its own prospective rationale.", ""]
(H / "READING.md").write_text("\n".join(L))
print("ok", json.dumps({k: out[k] for k in ("value", "totals", "per_reader")}), "stock-05", s05, "stock-03", s03, "full05", full05, "one03", one03)
